"use client";

import { useMemo } from "react";
import { useSession } from "@clerk/nextjs";
import { createClient } from "@supabase/supabase-js";

/**
 * The browser client carries the signed-in Clerk token, the same as the
 * server client. Realtime uses it to open the socket, and the channel policy
 * reads the organization claim out of it.
 */
export function useSupabaseBrowserClient() {
  const { session } = useSession();

  return useMemo(() => {
    const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const key = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

    if (!url || !key || !session) return null;

    return createClient(url, key, {
      accessToken: async () => (await session.getToken()) ?? null,
    });
  }, [session]);
}
